from solution import is_simple_power
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def reference(x, n):
    """Obviously-correct model: exists k >= 0 with n**k == x.
    Negative k cannot yield a new integer equality except for
    n in (1, -1) which is already covered by k >= 0, and n==0
    raises. So k >= 0 is exhaustive for int equality.
    Uses Python ** semantics, so 0**0 == 1.
    """
    if n == 0:
        # 0**0 == 1, 0**k == 0 for k >= 1
        return x == 0 or x == 1
    if n == 1:
        return x == 1
    if n == -1:
        return x == 1 or x == -1
    # |n| >= 2: |n**k| strictly increasing in k
    p = 1  # n**0
    # bound iterations; abs grows fast so this is exhaustive for bounded x
    for _ in range(200):
        if p == x:
            return True
        # once |p| exceeds |x| (and |x| >= 1) it only grows
        if abs(p) > abs(x) and abs(x) >= 1:
            return False
        # x == 0 can never be hit when n != 0
        if x == 0:
            return False
        p = p * n
    return False


# ---- explicit spec examples ----
@pytest.mark.parametrize(
    "x,n,expected",
    [
        (1, 4, True),
        (2, 2, True),
        (8, 2, True),
        (3, 2, False),
        (3, 1, False),
        (5, 3, False),
    ],
)
def test_spec_examples(x, n, expected):
    assert is_simple_power(x, n) is expected


def test_spec_example_3_1_is_false():
    # pinned regression: 1**k == 1, never 3
    assert is_simple_power(3, 1) is False


def test_one_is_power_of_nonzero_n():
    # n**0 == 1 for every n != 0
    for n in [-10, -2, -1, 1, 2, 3, 4, 100]:
        assert is_simple_power(1, n) is True


def test_n_equals_1_only_one():
    assert is_simple_power(1, 1) is True
    for x in [-5, -1, 0, 2, 3, 5, 100]:
        assert is_simple_power(x, 1) is False


def test_zero_base():
    # 0**1 == 0 so (0,0) is a power; nonzero base never gives 0
    assert is_simple_power(0, 0) is True
    for n in [-3, -2, -1, 1, 2, 3]:
        assert is_simple_power(0, n) is False


def test_minus_one_base():
    assert is_simple_power(1, -1) is True
    assert is_simple_power(-1, -1) is True
    assert is_simple_power(0, -1) is False
    assert is_simple_power(2, -1) is False
    assert is_simple_power(-2, -1) is False


# ---- property-based tests ----

@given(st.integers(min_value=-5, max_value=5), st.integers(min_value=0, max_value=10))
def test_generated_powers_are_true(n, k):
    # n**k must be recognised; skip huge values for speed
    x = n ** k
    assume(abs(x) < 10**6)
    assert is_simple_power(x, n) is True


@given(st.integers(min_value=2, max_value=10**6))
def test_n_equals_1_property(x):
    assume(x != 1)
    assert is_simple_power(x, 1) is False


@given(st.integers(min_value=-10, max_value=10).filter(lambda v: v != 0))
def test_one_is_power_property(n):
    assert is_simple_power(1, n) is True


@given(
    st.integers(min_value=-10, max_value=10),
    st.integers(min_value=-10, max_value=10),
)
def test_equivalence_to_reference_small(x, n):
    assert is_simple_power(x, n) is reference(x, n)


@given(
    st.integers(min_value=-1000, max_value=1000),
    st.integers(min_value=-5, max_value=5),
)
def test_equivalence_to_reference_medium(x, n):
    assert is_simple_power(x, n) is reference(x, n)


@given(st.integers(min_value=-4, max_value=4), st.integers(min_value=0, max_value=12))
def test_power_successor_fails_unless_same(n, k):
    # n**k + 1 is generally not a power; check against reference
    # (reference decides; this stresses off-by-one around exact powers)
    if n in (0, 1, -1):
        return
    x = n**k
    assume(abs(x) < 10**6)
    for delta in (1, -1):
        y = x + delta
        if y != x and reference(y, n) is False:
            assert is_simple_power(y, n) is False


@given(st.integers(min_value=2, max_value=5), st.integers(min_value=0, max_value=8))
def test_sign_property_positive_base(n, k):
    x = n**k
    assert is_simple_power(x, n) is True
    # negating a positive power (except trivial) is not a power of positive base
    if x != 0 and reference(-x, n) is False:
        assert is_simple_power(-x, n) is False
